-- Genshin: per-character farming attributes (talent books, boss drop, weekly mat, specialty, common drop) for the resin planner.
-- Run once after 0007 (safe to re-run). Adds characters the master list is missing. Source: the Resin Planner sheet, Oct 2026.
create temp table _gfarm(name text, rarity int, element text, weapon text, region text, farm jsonb);
-- characters missing from the master list are added as released, limited by rarity (admins can fix)
select 'genshin', g.name, g.rarity, g.element, g.weapon, nullif(g.region,''), false, true, 'resin-planner', g.farm
from _gfarm g where not exists (select 1 from public.characters c where c.game_id='genshin' and lower(c.name)=lower(g.name));
update public.characters c set farm = g.farm, element = coalesce(c.element, g.element), weapon_type = coalesce(c.weapon_type, g.weapon)
from _gfarm g where c.game_id='genshin' and lower(c.name)=lower(g.name);
select (select count(*) from public.characters where game_id='genshin' and farm <> '{}'::jsonb) as with_farm,
       (select count(*) from public.characters where game_id='genshin' and (farm is null or farm = '{}'::jsonb)) as without_farm,
       (select string_agg(name, ', ') from public.characters where game_id='genshin' and (farm is null or farm = '{}'::jsonb)) as names_without;
drop table _gfarm;